export default function LabeledCheckbox({ id, label, checked, onChange }) {
  return (
    <div className="CheckboxGroup">
      <input
        type="checkbox"
        id={id}
        checked={checked}
        onChange={(e) => setIsAgreed(e.target.checked)}
        className="Checkbox"
      />
      <label htmlFor={id} className="CheckboxLabel">
        {label}
      </label>
    </div>
  );
}
